// ---- user globals ----
// Centered text on the 160x80 screen (canvas mode: caller does display()).
void showCentered(const char* text, uint16_t color) {
  st7735_tft.setTextSize(2);
  st7735_tft.setTextColor(color);
  int16_t x = (st7735_tft.width() - st7735_tft.textWidth(text)) / 2;
  int16_t y = (st7735_tft.height() - st7735_tft.lineHeight()) / 2;
  st7735_tft.setCursor(x < 0 ? 0 : x, y < 0 ? 0 : y);
  st7735_tft.print(text);
}

