void setup() {
    Serial.setRxBufferSize(4096);   // room for a burst of actions from the host
    Serial.begin(115200);
    Serial.setTxTimeoutMs(0);    // Don't block when no host is listening

    st7735_tft.begin();
    st7735_tft.clear();

    button.begin();

    // ---- user setup ----
    st7735_tft.clear();
    showCentered("Atech OK", ST7735_TFT::COLOR_WHITE);
    st7735_tft.display();
    button.off();

    // ---- atech boot diagnostics (read by `atech check`) ----
    {
    esp_reset_reason_t _rr = esp_reset_reason();
    const char* _rrs;
    switch (_rr) {
        case ESP_RST_POWERON:   _rrs = "POWERON";   break;
        case ESP_RST_EXT:       _rrs = "EXT";       break;
        case ESP_RST_SW:        _rrs = "SOFTWARE";  break;
        case ESP_RST_PANIC:     _rrs = "PANIC";     break;
        case ESP_RST_INT_WDT:   _rrs = "INT_WDT";   break;
        case ESP_RST_TASK_WDT:  _rrs = "TASK_WDT";  break;
        case ESP_RST_WDT:       _rrs = "WDT";       break;
        case ESP_RST_BROWNOUT:  _rrs = "BROWNOUT";  break;
        case ESP_RST_DEEPSLEEP: _rrs = "DEEPSLEEP"; break;
        default:                _rrs = "UNKNOWN";   break;
    }
    Serial.print("{\"type\":\"boot\",\"payload\":{\"reset_reason\":\"");
    Serial.print(_rrs);
    Serial.print("\",\"free_heap\":");
    Serial.print((unsigned)ESP.getFreeHeap());
    Serial.print(",\"modules\":[");
    Serial.print("{\"instance\":\"st7735_tft\",\"module\":\"st7735_tft\",\"ok\":");
    Serial.print("true");
    Serial.print(",\"detectable\":false}");
    Serial.print(",{\"instance\":\"button\",\"module\":\"button\",\"ok\":");
    Serial.print("true");
    Serial.print(",\"detectable\":false}");
    Serial.println("]}}");
    }
}

void loop() {
    atechPollAction();   // one action per pass; module actions are handled here
    // Events are derived from the pin level, never from wasPressed()/wasReleased():
    // those consume the edge, and they belong to the user's code: block.
    static bool button_evDown = false;
    static unsigned long button_evAt = 0;
    if (button.isPressed() != button_evDown && millis() - button_evAt >= 20) {
      button_evDown = !button_evDown;
      button_evAt = millis();
      Serial.printf("{\"type\":\"event\",\"payload\":{\"event_type\":\"button\",\"key\":\"button\",\"value\":%d,\"source\":\"button\"}}\n", button_evDown ? 1 : 0);
    }

    // ---- user loop ----
    // isPressed() polls the level, so the firmware's own press/release events
    // ("button", 1/0) keep working. Redraw only when the state changes, so the
    // boot message stays until the first press.
    static bool wasDown = false;
    bool down = button.isPressed();
    if (down != wasDown) {
      wasDown = down;
      if (down) {
        st7735_tft.fillRect(0, 0, st7735_tft.width(), st7735_tft.height(), ST7735_TFT::COLOR_GREEN);
        showCentered("PRESSED", ST7735_TFT::COLOR_BLACK);
        button.setColor(0, 255, 0);
      } else {
        st7735_tft.clear();
        showCentered("ready", ST7735_TFT::COLOR_WHITE);
        button.off();
      }
      st7735_tft.display();
    }

    atechFinishAction(); // an action nobody handled is answered with ok:false
}
